from typing import List

class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        # Collect all indices where the element is x
        positions = []
        for i, num in enumerate(nums):
            if num == x:
                positions.append(i)

        # Process each query
        result = []
        for q in queries:
            if q <= len(positions):
                result.append(positions[q - 1])
            else:
                result.append(-1)

        return result

