import sys

def main():
    N = int(sys.stdin.readline())
    grid = [sys.stdin.readline().strip() for _ in range(N)]

    players = []
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'P':
                players.append((i, j))

    p1, p2 = players[0], players[1]

    # Normalize initial state
    if p1 < p2:
        initial_state = (p1[0], p1[1], p2[0], p2[1])
    else:
        initial_state = (p2[0], p2[1], p1[0], p1[1])

    visited = set()
    queue = deque()
    queue.append((initial_state[0], initial_state[1], initial_state[2], initial_state[3], 0))
    visited.add((initial_state[0], initial_state[1], initial_state[2], initial_state[3]))

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        x1, y1, x2, y2, steps = queue.popleft()

        # Check if players meet
        if x1 == x2 and y1 == y2:
            print(steps)
            return

        for dx, dy in directions:
            # Compute new positions for player 1
            nx1, ny1 = x1 + dx, y1 + dy
            if 0 <= nx1 < N and 0 <= ny1 < N and grid[nx1][ny1] != '#':
                new_x1, new_y1 = nx1, ny1
            else:
                new_x1, new_y1 = x1, y1

            # Compute new positions for player 2
            nx2, ny2 = x2 + dx, y2 + dy
            if 0 <= nx2 < N and 0 <= ny2 < N and grid[nx2][ny2] != '#':
                new_x2, new_y2 = nx2, ny2
            else:
                new_x2, new_y2 = x2, y2

            # Check if they meet after this move
            if new_x1 == new_x2 and new_y1 == new_y2:
                print(steps + 1)
                return

            # Normalize the new state
            if (new_x1, new_y1) < (new_x2, new_y2):
                new_state = (new_x1, new_y1, new_x2, new_y2)
            else:
                new_state = (new_x2, new_y2, new_x1, new_y1)

            if new_state not in visited:
                visited.add(new_state)
                queue.append((new_state[0], new_state[1], new_state[2], new_state[3], steps + 1))

    print(-1)

if __name__ == "__main__":
    main()

import sys

def main():
    T = sys.stdin.readline().strip()
    N = int(sys.stdin.readline())
    bags = []
    for _ in range(N):
        parts = sys.stdin.readline().split()
        A_i = int(parts[0])
        strings = parts[1:]
        bags.append(strings)

    len_T = len(T)
    INF = float('inf')
    dp = [[INF] * (len_T + 1) for _ in range(N + 1)]
    dp[0][0] = 0

    for i in range(1, N + 1):
        current_bag = bags[i-1]
        for j in range(len_T + 1):
            # Do nothing
            if dp[i][j] > dp[i-1][j]:
                dp[i][j] = dp[i-1][j]
            # Take a string from current bag
            for s in current_bag:
                len_s = len(s)
                if j + len_s <= len_T and T[j:j+len_s] == s:
                    if dp[i][j + len_s] > dp[i-1][j] + 1:
                        dp[i][j + len_s] = dp[i-1][j] + 1

    result = dp[N][len_T]
    print(-1 if result == INF else result)

if __name__ == "__main__":
    main()
